recommendation:
Replace the free-form string parameter with an enumerated reward identifier (e.g. uint8 rewardId) and maintain an owner-controlled mapping of valid reward IDs to descriptions. This constrains what can appear in event logs to only administrator-approved values. Example refactor:

solidity
// Owner-managed reward catalogue
mapping(uint8 => string) public rewardCatalogue;

function setReward(uint8 id, string calldata description) external onlyOwner {
    rewardCatalogue[id] = description;
}

function burn(uint256 amount, uint8 rewardId) public {
    require(amount > 0, "CafeToken: quantidade invalida");
    require(bytes(rewardCatalogue[rewardId]).length > 0, "CafeToken: recompensa invalida");
    require(balanceOf(msg.sender) >= amount, "CafeToken: saldo insuficiente");
    _burn(msg.sender, amount);
    emit RewardRedeemed(msg.sender, amount, rewardId);
}

This ensures only legitimate, pre-approved rewards are ever recorded on-chain.

codeSnippet:
function burn(uint256 amount, string memory recompensa) public {
    require(amount > 0, "CafeToken: a quantidade a queimar deve ser maior que zero");
    require(balanceOf(msg.sender) >= amount, "CafeToken: saldo insuficiente para queimar tokens");
    _burn(msg.sender, amount);
    emit RewardRedeemed(msg.sender, amount, recompensa); // <-- arbitrary user input emitted as event data
}
